def forward(groups):
    date_part, time_part = groups
    dt = datetime.strptime(f'2022-{date_part} {time_part}', '%Y-%m-%d %H:%M:%S.%f')
    return {'stored': [int(dt.timestamp() * 1000)], 'layout': []}

def inverse(record):
    millis = int(record['stored'][0])
    dt = datetime.fromtimestamp(millis / 1000)
    return dt.strftime('%m-%d %H:%M:%S.%f')[:-3]

